const CustomDropdown = ({ icon: Icon, value, options, onChange, placeholder }: any) => {
  const [isOpen, setIsOpen] = useState(false);
  return (
    <div className="relative">
      <div className="absolute inset-y-0 left-0 pl-4 flex items-center pointer-events-none z-10">
         <Icon className={`w-5 h-5 transition-colors ${isOpen ? 'text-cyan-400' : 'text-gray-500'}`} />
      </div>
      <div 
        onClick={() => setIsOpen(!isOpen)}
        className={`w-full cursor-pointer bg-black/40 border ${isOpen ? 'border-cyan-500 shadow-[0_0_15px_rgba(6,182,212,0.3)]' : 'border-white/10'} text-white pl-12 pr-10 py-4 rounded-xl font-bold transition-all outline-none backdrop-blur-md flex items-center justify-between hover:border-cyan-500/50`}
      >
        <span className={value ? "text-white" : "text-gray-500"}>{value || placeholder}</span>
        <svg className={`w-5 h-5 text-gray-500 transition-transform duration-300 ${isOpen ? 'rotate-180 text-cyan-400' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 9l-7 7-7-7"></path></svg>
      </div>

      {isOpen && (
        <>
          <div className="fixed inset-0 z-40" onClick={() => setIsOpen(false)}></div>
          <div className="absolute top-full left-0 right-0 mt-2 bg-[#0a0a0c]/95 backdrop-blur-xl border border-white/10 rounded-xl shadow-[0_10px_40px_rgba(0,0,0,0.8)] z-50 max-h-60 overflow-y-auto py-2">
            {options.map((opt: string) => (
              <div 
                key={opt}
                onClick={() => { onChange(opt); setIsOpen(false); }}
                className={`px-6 py-3 cursor-pointer transition-colors font-bold ${value == opt ? 'bg-cyan-500/20 text-cyan-400' : 'text-gray-300 hover:bg-white/5 hover:text-white'}`}
              >
                {opt}
              </div>
            ))}
          </div>
        </>
      )}
    </div>
  );
};

