const LicensePlateInput = ({ value, onChange, icon: Icon }: any) => {
  const [isFocused, setIsFocused] = useState(false);

  return (
    <div className="relative group h-[58px]">
      <div className="absolute inset-y-0 left-0 pl-4 flex items-center pointer-events-none z-10">
         <Icon className={`w-5 h-5 transition-colors ${isFocused ? 'text-emerald-400' : 'text-gray-500'}`} />
      </div>

      <input 
        type="text" 
        value={value} 
        onChange={(e) => onChange(e.target.value.toUpperCase())}
        onFocus={() => setIsFocused(true)}
        onBlur={() => setIsFocused(false)}
        className="absolute inset-0 w-full h-full opacity-0 cursor-text z-20"
        maxLength={12}
        autoComplete="off"
        spellCheck="false"
      />

      <div className={`w-full h-full bg-black/40 border ${isFocused ? 'border-emerald-500 shadow-[0_0_15px_rgba(16,185,129,0.3)]' : 'border-white/10'} pl-12 pr-4 flex items-center rounded-xl transition-all backdrop-blur-md overflow-hidden`}>
        {value ? (
          <div className="flex items-center gap-1.5">
            {value.split('').map((char: string, i: number) => {
              const isPunctuation = char === '-' || char === '.';
              return (
                <div key={i} className={`flex items-center justify-center font-mono font-black ${isPunctuation ? 'text-emerald-500/50 text-xl w-3' : 'w-7 h-9 text-lg md:w-8 md:h-10 md:text-xl bg-gradient-to-b from-emerald-500/20 to-emerald-500/5 border border-emerald-500/30 text-emerald-400 rounded-lg shadow-[inset_0_0_8px_rgba(16,185,129,0.2)]'}`}>
                  {char}
                </div>
              );
            })}
            {isFocused && value.length < 12 && (
              <div className="w-0.5 h-6 bg-emerald-400 animate-pulse ml-1"></div>
            )}
          </div>
        ) : (
          <div className="flex items-center gap-1.5 opacity-30">
             {['3','0','G'].map((c, i) => <div key={i} className="flex items-center justify-center w-7 h-9 md:w-8 md:h-10 text-lg md:text-xl border border-white/20 text-white rounded-lg">{c}</div>)}
             <div className="text-white/50 text-xl w-3 text-center">-</div>
             {['8','8','8','8','8'].map((c, i) => <div key={i} className="flex items-center justify-center w-7 h-9 md:w-8 md:h-10 text-lg md:text-xl border border-white/20 text-white rounded-lg">{c}</div>)}
          </div>
        )}
      </div>
    </div>
  );
};

