const LicensePlateInput = ({ value, onChange, icon: Icon }: any) => {
  const [isFocused, setIsFocused] = useState(false);
  const maxLength = 10;

  return (
    <div className="relative group h-[58px]">
      <div className="absolute inset-y-0 left-0 pl-4 flex items-center pointer-events-none z-10">
         <Icon className={`w-5 h-5 transition-colors ${isFocused ? 'text-emerald-400' : 'text-gray-500'}`} />
      </div>

      <input 
        type="text" 
        value={value} 
        onChange={(e) => onChange(e.target.value.toUpperCase())}
        onFocus={() => setIsFocused(true)}
        onBlur={() => setIsFocused(false)}
        className="absolute inset-0 w-full h-full opacity-0 cursor-text z-20"
        maxLength={maxLength}
        autoComplete="off"
        spellCheck="false"
      />

      <div className={`w-full h-full bg-black/40 border ${isFocused ? 'border-emerald-500 shadow-[0_0_15px_rgba(16,185,129,0.3)]' : 'border-white/10'} pl-12 pr-4 flex items-center rounded-xl transition-all backdrop-blur-md overflow-hidden`}>
        <div className="flex items-center gap-1.5">
          {Array.from({ length: maxLength }).map((_, i) => {
            const char = value[i];
            const isPunctuation = char === '-' || char === '.';
            const isActive = isFocused && value.length === i;

            let boxStyle = "w-7 h-9 md:w-8 md:h-10 text-lg md:text-xl border border-white/10 bg-black/50 text-gray-600";
            if (char) {
              boxStyle = isPunctuation 
                ? "w-3 text-emerald-500/50 text-xl bg-transparent border-none" 
                : "w-7 h-9 md:w-8 md:h-10 text-lg md:text-xl bg-gradient-to-b from-emerald-500/20 to-emerald-500/5 border border-emerald-500/50 text-emerald-400 shadow-[inset_0_0_8px_rgba(16,185,129,0.3)] scale-110";
            } else if (isActive) {
              boxStyle = "w-7 h-9 md:w-8 md:h-10 text-lg md:text-xl border-2 border-emerald-400 border-dashed animate-pulse bg-emerald-500/10 shadow-[0_0_10px_rgba(16,185,129,0.4)]";
            }

            return (
              <div key={i} className={`flex items-center justify-center font-mono font-black rounded-lg transition-all duration-300 ${boxStyle}`}>
                {char || ''}
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
};

